package cu.hogarplaya;
import org.json.*;import java.util.*;import java.util.concurrent.*;import android.app.Activity;
public class ExpensePurchasesTest {
 static int checks;static final String SHARED="11111111-1111-4111-8111-111111111111";
 static void ok(boolean x){checks++;if(!x)throw new AssertionError("Comprobación "+checks);}
 interface Run{void run()throws Exception;}static void fails(Run r)throws Exception{boolean failed=false;try{r.run();}catch(Exception e){failed=true;}ok(failed);}
 static JSONObject line(String id,String format)throws Exception{return new JSONObject().put("id",id).put("productId","arroz").put("name","Arroz").put("category","Canasta básica").put("quantity","3").put("unitCode","lb").put("unit","lb").put("unitPrice","200").put("currency","CUP").put("rate","910").put("paymentFormat",format).put("planId","");}
 static AppStore setup()throws Exception {AppStore s=new AppStore();AppStore.current=s;s.prefs.values.put("householdId","home");s.prefs.values.put("authenticatedDay","2026-11-09");s.snap.put("cupCash",0).put("cupTransfer",0).put("usd",41000);s.saveCart("ana",new JSONArray().put(line("a","Efectivo")).put(line("b","Transferencia")));JSONObject v=new JSONObject().put("householdId","home").put("products",new JSONArray()).put("offers",new JSONArray()).put("shared",new JSONArray()).put("queue",new JSONArray()).put("conflicts",new JSONArray());HouseholdFeatures.store(s,v);return s;}
 static JSONObject request(AppStore s,String line)throws Exception{return new JSONObject().put("requestId",UUID.randomUUID().toString()).put("date","2026-11-09").put("place","Mercado ficticio").put("fundCategory","").put("items",s.cart("ana")).put("lineId",line).put("line",new JSONObject(s.cart("ana").getJSONObject(line.equals("a")?0:1).toString()));}
 static int count(AppStore s){return s.db.data.getJSONObject("ops").length();}
 static JSONObject first(AppStore s){JSONObject ops=s.db.data.getJSONObject("ops");return ops.getJSONObject(ops.keySet().iterator().next());}
 static JSONObject location(){return new JSONObject().put("place","Mercado ficticio").put("status","disabled");}
 static JSONObject shared(AppStore s,boolean linked)throws Exception {JSONObject v=HouseholdFeatures.get(s),item=new JSONObject().put("id",SHARED).put("name","Arroz").put("quantity",3).put("unit","lb").put("revision",2).put("bought",false).put("deleted",false);v.getJSONArray("shared").put(item);if(linked){JSONObject owners=new JSONObject().put(SHARED,new JSONObject().put("actorId","ana").put("lineId","a").put("scope","cart").put("lastLine",SharedCartPlan.item(line("a","Efectivo"))).put("seenRevision",2));v.put("sharedCartOwners",owners);}HouseholdFeatures.store(s,v);return new JSONObject().put("requestId",UUID.randomUUID().toString()).put("date","2026-11-09").put("fundCategory","").put("sharedItem",new JSONObject(item.toString()).put("pendingChangeId","")).put("line",line("shared-buy","Transferencia"));}
 static void auth(JSONObject q,boolean location)throws Exception{HouseholdFeatures.replied=new CountDownLatch(1);HouseholdFeatures.error=null;HouseholdFeatures.answer=null;PurchaseLocation.captured=new CountDownLatch(1);ok(ExpenseBridge.intercept(new Activity(),q.toString()));if(location){ok(PurchaseLocation.captured.await(3,TimeUnit.SECONDS));PurchaseLocation.waiting.accept(location());}ok(HouseholdFeatures.replied.await(3,TimeUnit.SECONDS));}
 public static void main(String[] args)throws Exception {
  try {
   AppStore s=setup();JSONObject req=request(s,"a");req.getJSONObject("line").put("quantity","1");JSONObject result=ExpensePurchases.purchase(s,"ana","featuresPurchaseCart",req,location());ok(count(s)==1);ok(s.cart("ana").length()==2);ok(s.cart("ana").getJSONObject(0).getString("quantity").equals("2"));ok(s.cart("ana").getJSONObject(1).getString("quantity").equals("3"));ok(first(s).getString("amount").equals("200.00"));ok(first(s).getString("paymentFormat").equals("Efectivo"));ok(first(s).getJSONObject("location").getString("place").equals("Mercado ficticio"));ok(result.getJSONArray("expenseWarnings").length()>0);
   ExpensePurchases.purchase(s,"ana","featuresPurchaseCart",req,location());ok(count(s)==1);final AppStore a=s;final JSONObject r=req;fails(()->ExpensePurchases.purchase(a,"otro","featuresPurchaseCart",r,location()));JSONObject altered=new JSONObject(req.toString()).put("fundCategory","Fondo casa");fails(()->ExpensePurchases.purchase(a,"ana","featuresPurchaseCart",altered,location()));ok(count(s)==1);
   JSONObject next=request(s,"b");ExpensePurchases.purchase(s,"ana","featuresPurchaseCart",next,location());ok(count(s)==2);ok(s.cart("ana").length()==1);ok(s.cart("ana").getJSONObject(0).getString("id").equals("a"));
   s=setup();req=request(s,"a");req.remove("lineId");req.remove("line");result=ExpensePurchases.purchase(s,"ana","cartCheckoutLocated",req,location());ok(result.getInt("savedCount")==2);ok(s.cart("ana").length()==0);ok(count(s)==2);ExpensePurchases.purchase(s,"ana","cartCheckoutLocated",req,location());ok(count(s)==2);
   s=setup();req=request(s,"a");s.db.failUpdate=true;String before=s.db.data.toString();final AppStore b=s;final JSONObject rr=req;fails(()->ExpensePurchases.purchase(b,"ana","featuresPurchaseCart",rr,location()));ok(before.equals(s.db.data.toString()));ExpensePurchases.purchase(s,"ana","featuresPurchaseCart",req,location());ok(count(s)==1);
   s=setup();req=request(s,"a");req.getJSONObject("line").put("quantity","4");final AppStore c=s;final JSONObject over=req;fails(()->ExpensePurchases.purchase(c,"ana","featuresPurchaseCart",over,location()));ok(count(s)==0);ok(s.cart("ana").length()==2);
   s=setup();req=request(s,"a");s.saveCart("ana",new JSONArray().put(line("a","Efectivo")));final AppStore d=s;final JSONObject stale=req;fails(()->ExpensePurchases.purchase(d,"ana","featuresPurchaseCart",stale,location()));ok(count(s)==0);
   s=setup();req=request(s,"a");req.put("fundCategory","falso");final AppStore e=s;final JSONObject invalid=req;fails(()->ExpensePurchases.purchase(e,"ana","featuresPurchaseCart",invalid,location()));ok(count(s)==0);
   s=setup();req=request(s,"a");req.put("fundCategory","Fondo casa");ExpensePurchases.purchase(s,"ana","featuresPurchaseCart",req,location());ok(count(s)==1);ok(first(s).getString("fundCategory").equals("Fondo casa"));
   s=setup();req=shared(s,true);req.getJSONObject("line").put("quantity","1");ExpensePurchases.purchase(s,"ana","featuresPurchaseShared",req,location());ok(count(s)==1);ok(s.cart("ana").getJSONObject(0).getString("quantity").equals("2"));JSONObject v=HouseholdFeatures.get(s);ok(v.getJSONArray("queue").length()==1);ok(v.getJSONArray("queue").getJSONObject(0).getJSONObject("item").getDouble("quantity")==2);ok(!v.getJSONArray("queue").getJSONObject(0).getJSONObject("item").getBoolean("bought"));ExpensePurchases.purchase(s,"ana","featuresPurchaseShared",req,location());ok(count(s)==1);
   s=setup();req=shared(s,false);ExpensePurchases.purchase(s,"ana","featuresPurchaseShared",req,location());ok(count(s)==1);ok(s.cart("ana").length()==2);ok(HouseholdFeatures.get(s).getJSONArray("queue").getJSONObject(0).getJSONObject("item").getBoolean("bought"));final AppStore f=s;final JSONObject already=new JSONObject(req.toString()).put("requestId",UUID.randomUUID().toString());fails(()->ExpensePurchases.purchase(f,"ana","featuresPurchaseShared",already,location()));ok(count(s)==1);
   s=setup();req=shared(s,false);v=HouseholdFeatures.get(s);v.getJSONArray("shared").getJSONObject(0).put("quantity",4);HouseholdFeatures.store(s,v);final AppStore g=s;final JSONObject staleShared=req;fails(()->ExpensePurchases.purchase(g,"ana","featuresPurchaseShared",staleShared,location()));ok(count(s)==0);ok(HouseholdFeatures.get(s).getJSONArray("queue").length()==0);
   s=setup();req=shared(s,false);s.failCache="features160";before=s.db.data.toString();final AppStore h=s;final JSONObject sharedFail=req;fails(()->ExpensePurchases.purchase(h,"ana","featuresPurchaseShared",sharedFail,location()));ok(before.equals(s.db.data.toString()));
   s=setup();req=shared(s,false);v=HouseholdFeatures.get(s);v.getJSONArray("conflicts").put(new JSONObject().put("local",new JSONObject().put("entityId",SHARED)));HouseholdFeatures.store(s,v);final AppStore i=s;final JSONObject conflict=req;fails(()->ExpensePurchases.purchase(i,"ana","featuresPurchaseShared",conflict,location()));ok(count(s)==0);
   s=setup();JSONObject expense=new JSONObject().put("id",UUID.randomUUID().toString()).put("type","Gasto").put("category","Canasta básica").put("date","2026-11-09").put("currency","USD").put("amount","20.00").put("concept","Compra real").put("fundCategory","");ExpensePurchases.save(s,"ana",expense,false);ok(count(s)==1);ExpensePurchases.save(s,"ana",expense,false);ok(count(s)==1);first(s).put("status","REJECTED").put("location",location());ExpensePurchases.save(s,"ana",expense,true);ok(count(s)==1);ok(first(s).has("location"));
   final AppStore j=s;final JSONObject synced=expense;fails(()->ExpensePurchases.save(j,"ana",synced,true));ok(count(s)==1);
   s=setup();HouseholdFeatures.active="";JSONObject q=new JSONObject().put("id","auth-test").put("action","save").put("data",expense);auth(q,false);ok(HouseholdFeatures.error!=null);ok(count(s)==0);
   HouseholdFeatures.active="ana";auth(q,false);ok(HouseholdFeatures.error==null);ok(count(s)==1);
   s=setup();req=request(s,"a");q=new JSONObject().put("id","purchase-auth").put("action","featuresPurchaseCart").put("data",req);HouseholdFeatures.replied=new CountDownLatch(1);PurchaseLocation.captured=new CountDownLatch(1);ok(ExpenseBridge.intercept(new Activity(),q.toString()));ok(PurchaseLocation.captured.await(3,TimeUnit.SECONDS));HouseholdFeatures.active="otra";PurchaseLocation.waiting.accept(location());ok(HouseholdFeatures.replied.await(3,TimeUnit.SECONDS));ok(HouseholdFeatures.error!=null);ok(count(s)==0);ok(s.cart("ana").length()==2);
   // Una compra compartida que venía de Modo compra conserva el gasto de la jornada.
   HouseholdFeatures.active="ana";s=setup();s.activeShopping=true;Shopping.saveLine(s,line("mode-a","Efectivo"));req=shared(s,false);v=HouseholdFeatures.get(s);v.put("sharedCartOwners",new JSONObject().put(SHARED,new JSONObject().put("actorId","ana").put("scope","shopping").put("lineId","mode-a").put("seenRevision",2).put("lastLine",SharedCartPlan.item(line("mode-a","Efectivo")))));HouseholdFeatures.store(s,v);req.getJSONObject("line").put("quantity","1");ExpensePurchases.purchase(s,"ana","featuresPurchaseShared",req,location());ok(count(s)==1);ok(first(s).getJSONObject("shopping").getString("id").equals("mode-session"));ok(Shopping.modes(s).getJSONObject("mode-a").getLong("chargedCents")==20000);String restId=HouseholdFeatures.get(s).getJSONObject("sharedCartOwners").getJSONObject(SHARED).getString("lineId");ok(!restId.equals("mode-a"));ok(Shopping.modes(s).getJSONObject(restId).getString("quantity").equals("2"));ok(!Shopping.modes(s).getJSONObject(restId).optBoolean("bought"));ok(s.cart("ana").length()==2);
   // Otra compra parcial antes de recibir respuesta de la lista no pisa su cola.
   JSONObject pending=ExpensePurchases.sharedCurrent(HouseholdFeatures.get(s),SHARED);JSONObject again=new JSONObject(req.toString()).put("requestId",UUID.randomUUID().toString()).put("sharedItem",pending);again.getJSONObject("line").put("quantity","1");ExpensePurchases.purchase(s,"ana","featuresPurchaseShared",again,location());ok(count(s)==2);ok(Shopping.modes(s).getJSONObject(restId).optBoolean("bought"));ok(HouseholdFeatures.get(s).getJSONArray("queue").length()==1);ok(HouseholdFeatures.get(s).getJSONObject("sharedIntents").getJSONObject(SHARED).getJSONObject("item").getDouble("quantity")==1);
   final AppStore mode=s;JSONObject wrongSession=new JSONObject().put("id","mode-a").put("sessionId","otra");fails(()->ExpensePurchases.shopping(mode,"ana",wrongSession,location()));ok(count(s)==2);
   JSONObject correctSession=new JSONObject().put("id","mode-a").put("sessionId","mode-session");ExpensePurchases.shopping(s,"ana",correctSession,location());ok(count(s)==2);
   // Sobrepasar el límite explícito revierte cantidad, gasto y cola en conjunto.
   pending=ExpensePurchases.sharedCurrent(HouseholdFeatures.get(s),SHARED);JSONObject overMode=new JSONObject(again.toString()).put("requestId",UUID.randomUUID().toString()).put("sharedItem",pending);overMode.getJSONObject("line").put("unitPrice","10000");before=s.db.data.toString();fails(()->ExpensePurchases.purchase(mode,"ana","featuresPurchaseShared",overMode,location()));ok(before.equals(s.db.data.toString()));
   System.out.println("PASS native Java: "+checks+" comprobaciones; compras parciales, recibos, rollback, reservas informativas, cola compartida y sesión.");
  }finally{SyncEngine.WORK.shutdownNow();}
 }
}
